  const atEnd = () => i >= s.length

  function quoted(q) {
    i++
    let out = ''
    for (;;) {
      if (i >= s.length) fail('unterminated string')
      const c = s[i]
      if (c === q) { i++; return out }
      if (q === "'" || c !== '\\') { out += c; i++; continue }
      i++
      if (i >= s.length) fail('unterminated string')
      const e = s[i]
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) { out += map[e]; i++ } else if (e === 'u') {
        const h = s.slice(i + 1, i + 5)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        i += 5
      } else fail('invalid escape \\' + e)
    }
  }

  function name() {
    const c = peek()
    if (c === '"' || c === "'") return quoted(c)
    const st = i
    while (isBare(s[i])) i++
    if (i === st) fail('expected a name')
    return s.slice(st, i)
  }

  function dotted() {
    const parts = [name()]
    for (;;) {
      const save = i
      while (i < s.length && isWs(s[i])) i++
      if (s[i] === '.') {
        i++
        while (i < s.length && isWs(s[i])) i++
        parts.push(name())
      } else { i = save; return parts }
    }
  }

  function value() {
    while (i < s.length && isWs(s[i])) i++
    if (atEnd() || ',]}#;'.includes(s[i])) fail('expected a value')
    const c = s[i]
    if (c === '"') return { t: 'string', v: quoted('"') }
    if (c === "'") return { t: 'string', v: quoted("'") }
    if (c === '[') {
      i++
      const items = []
      for (;;) {
        skipWs()
        if (atEnd()) fail('unterminated array')
        if (s[i] === ']') { i++; break }
        items.push(value())
        skipWs()
        if (atEnd()) fail('unterminated array')
        if (s[i] === ',') { i++; continue }
        if (s[i] === ']') { i++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      i++
      const tbl = newTable()
      let first = true
      for (;;) {
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        if (first && s[i] === '}') { i++; break }
        first = false
        const parts = dotted()
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        if (s[i] !== '=') fail('expected = in an inline table')
        i++
        const v = value()
        assign(tbl, parts, v, [])
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        if (s[i] === ',') { i++; continue }
        if (s[i] === '}') { i++; break }
        fail('unterminated inline table')
      }
      return tbl
    }
    const st = i
    while (i < s.length && !isWs(s[i]) && !',]}'.includes(s[i])) i++
    const tok = s.slice(st, i)
    if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
    const int = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp('^' + int + '$').test(tok)) return { t: 'integer', v: Number(tok.replace(/_/g, '')) }
    const fl = new RegExp('^' + int + '(?:\\.\\d+(?:_\\d+)*(?:[eE][+-]?\\d+(?:_\\d+)*)?|[eE][+-]?\\d+(?:_\\d+)*)$')
