    while (i < s.length && isWs(s[i])) i++
    if (s[i] !== ']') fail('unterminated table header')
    i++
    if (dbl) {
      if (s[i] !== ']') fail('unterminated table header')
      i++
    }
    skipWs()
    if (!atEnd()) fail('trailing text after a table header')
    let cur = root
    const path = []
    for (let k = 0; k < parts.length - 1; k++) {
      path.push(parts[k])
      cur = step(cur, parts[k], path)
    }
    const last = parts[parts.length - 1]
    path.push(last)
    const p = path.join('.')
    const ex = cur.map.get(last)
    if (dbl) {
      if (!ex) {
        const nt = newTable()
        cur.map.set(last, { t: 'array', items: [nt], aot: true })
        state.cur = nt
      } else if (ex.t === 'array' && ex.aot) {
        const nt = newTable()
        ex.items.push(nt)
        state.cur = nt
      } else fail(p + ' is not an array of tables')
    } else if (!ex) {
      const nt = newTable()
      nt.header = true
      cur.map.set(last, nt)
      state.cur = nt
    } else if (ex.t !== 'table') fail(p + ' is not a table')
    else if (ex.header) fail('table ' + p + ' is defined twice')
    else { ex.header = true; state.cur = ex }
