    for (const k of sortedKeys(n)) {
      const p = path === null ? k : path + '.' + k
      const c = n.map.get(k)
      out.push(p + ' ' + c.t)
      listKeys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, idx) => {
      const p = path + '[' + idx + ']'
      out.push(p + ' ' + c.t)
      listKeys(c, p, out)
    })
  }
